+
+// parseScript requires one complete JSON value and a matching file name.
+func parseScript(filename string, b []byte) (Script, error) {
+	dec := json.NewDecoder(strings.NewReader(string(b)))
+	dec.DisallowUnknownFields()
+	var s Script
+	if err := dec.Decode(&s); err != nil {
+		return Script{}, errors.New(filename + ": " + err.Error())
+	}
+	var trailing any
+	if err := dec.Decode(&trailing); err != io.EOF {
+		if err == nil {
+			err = errors.New("unexpected second JSON value")
+		}
+		return Script{}, errors.New(filename + ": " + err.Error())
+	}
+	if s.Name+".json" != filename {
+		return Script{}, errors.New(filename + ": name does not match the file")
+	}
+	return s, nil
